from author import put
F=lambda n,hc,ha,bc,ba:put('operations2','rst31-operations2-figure-'+n,{'caption':hc,'alt':ha},{'caption':bc,'alt':ba})
F('cost-comparison','मानक और वास्तविक को समान बिक्री की संरचना में तुलना करें।','दो स्तरीकृत स्तंभ मानक लागत 30％ और वास्तविक लागत 32％ दिखाते हैं। अंतर 2 प्रतिशत अंक है।','একই বিক্রির গঠনে মান ও প্রকৃত ব্যয় তুলনা করুন।','দুটি স্তূপিত বার মান ব্যয় 30％ ও প্রকৃত ব্যয় 32％ দেখায়; পার্থক্য 2 শতাংশ পয়েন্ট।')
F('hood-damper','हुड और डैम्पर का स्थान रूपरेखा-काट में देखें।','रसोई उपकरण के ऊपर हुड और ऊपर के डक्ट में डैम्पर दिखाने वाला काट-चित्र।','ধারণাগত ছেদচিত্রে হুড ও ড্যাম্পারের অবস্থান দেখুন।','রান্নার যন্ত্রের ওপর হুড এবং ওপরের ডাক্টে ড্যাম্পার দেখানো ছেদচিত্র।')
F('escape-route','धुएँ से बचने का मार्ग और निकलने के बाद की जाँच अलग करें।','धुएँ वाले निकास की ओर न जाकर दूसरी खुली जगह की ओर मार्ग दिखाने वाला स्वतंत्र योजना-चित्र।','ধোঁয়া এড়ানোর পথ ও বেরোনোর পরের যাচাই আলাদা করুন।','ধোঁয়াযুক্ত বেরোনোর দিক এড়িয়ে অন্য খোলা পথে যাওয়া দেখানো স্বতন্ত্র সমতল ধারণাচিত্র।')
